const CITY_CENTERS=Object.fromEntries(REGION_CATALOG.filter(r=>['municipality','district'].includes(r.kind)&&WEATHER_CITIES.includes(r.id)).map(r=>[r.id,[r.latitude,r.longitude]]));
function findNearestLocation(){if(!navigator.geolocation){toast('이 브라우저에서는 위치 기능을 사용할 수 없습니다. 지역을 직접 선택하세요.');return}const b=$('#nearestLocation');if(b){b.disabled=true;b.textContent='위치 확인 중'}navigator.geolocation.getCurrentPosition(p=>{const found=nearestCity(p.coords.latitude,p.coords.longitude,CITY_CENTERS);if(b){b.disabled=false;b.textContent='현재 위치에서 가까운 지원지역 찾기'}if(!found){toast('가까운 지원지역이 없습니다. 지역을 직접 선택하세요.');return}setWeatherCity(found.name,'current');$('#sheet').close();toast(found.name+' 가까운 지원지점의 날씨로 변경했습니다.');},()=>{if(b){b.disabled=false;b.textContent='현재 위치에서 가까운 지원지역 찾기'}toast('위치를 확인하지 못했습니다. 지역을 직접 선택하세요.');},{enableHighAccuracy:false,timeout:8000,maximumAge:300000})}

