function renderPublicSignals(){for(const[id,el]of[['weather','warningCoverage'],['fire','fireCoverage'],['landslide','landslideCoverage']]){const element=$('#'+el);element.setAttribute('aria-busy',String(publicSignalsLoading));const label=publicSignalsLoading&&!publicSignals.length?(regions.length?'관심지역':'전국')+' 확인 중':scopedPublicSignal(publicSignals.find(s=>s.id===id),regions).label;element.textContent=label.replace(/관심지역\s+/g, '');element.setAttribute('aria-label',label);element.dataset.resultState=publicResultState(label)}const v=scopedPublicSignal(publicSignals.find(s=>s.id==='weather'),regions);const warning=$('#warningCoverage');warning.textContent=warningSummary(v,{loading:publicSignalsLoading&&!publicSignals.length});$('#warningExtra').textContent=(v.pendingRecords||[]).length?'예비·발효 예정 '+v.pendingRecords.length+'건':'';$('#weatherWarningCard').classList.toggle('has-active-warning',v.records.length>0);updatePreviewContext({regions,publicLoading:publicSignalsLoading&&!publicSignals.length,publicViews:Object.fromEntries(['weather','fire','landslide'].map(id=>[id,scopedPublicSignal(publicSignals.find(s=>s.id===id),regions)]))})}
function refreshPublicSignals(){
 if(publicSignalsRequest)return publicSignalsRequest;
 publicSignalsLoading=true;renderPublicSignals();
 publicSignalsRequest=Promise.all(['weather','fire','landslide'].map(async id=>{
  try{const r=await fetch('/api/public-signals?part='+id,{cache:'no-store',signal:AbortSignal.timeout(28000)});if(!r.ok)throw Error();const d=await r.json();const next=d.signals?.find(s=>s.id===id);if(!next)throw Error();const retained=retainLastGood(publicSignals.find(s=>s.id===id),next);publicSignals=[...publicSignals.filter(s=>s.id!==id),retained?.fallback?{...retained,id,reason:'provider_fetch_failed'}:retained];}
  catch{const previous=publicSignals.find(s=>s.id===id);publicSignals=[...publicSignals.filter(s=>s.id!==id),previous?{...previous,stale:true,reason:'request_failed'}:{id,status:'unavailable',count:null,records:[],reason:'request_failed'}];}
  renderPublicSignals();
 })).finally(()=>{publicSignalsLoading=false;publicSignalsRequest=null;renderPublicSignals()});return publicSignalsRequest;
}
function publicSignalSheet(id){if(publicSignalsLoading&&!publicSignals.length){showSheet('공식 현황 확인 중','<p>선택한 지역의 공식 자료를 불러오고 있습니다. 조회가 끝나면 첫 화면에 결과를 표시합니다.</p>');return}const s=publicSignals.find(x=>x.id===id);const names={weather:'기상특보',fire:'산불 현황',landslide:'산사태 경보'};const v=scopedPublicSignal(s,regions);if(id==='weather'){showSheet(names[id],warningSheetHTML(s,v,regions,{stamp}));return;}showSheet(names[id],`<h3>${esc(v.label)}</h3><p>${regions.length?'관심지역: '+regions.map(esc).join(' · '):'전국 범위'}</p>${v.kind==='failed'?'<p>자료 조회에 실패해 현재 발표 유무를 알 수 없습니다. 새로고침하거나 공식 원문을 확인하세요.</p>':v.unknown?`<p>${v.unknownReason==='time'?'발효시각을 판별하지 못한 자료가 있어 현재 발효 건수를 확정하지 못했습니다.':'발표 지역을 판별하지 못한 자료가 있어 해당 지역의 건수를 확정하지 못했습니다.'} 아래 전국 발표 내용과 공식 원문을 확인하세요.</p>`:v.count===0?`<p>${id==='weather'?'해당 범위에 현재 발효 중인 기상특보가 없습니다. 예비·발효 예정 특보는 별도로 표시합니다.':'조회에 성공했으며 해당 범위의 공개목록에 발표된 항목이 없습니다. 아직 발표되지 않은 사고까지 없다는 뜻은 아닙니다.'}</p>`:''}${v.fallback?'<p>최신 조회에 실패하여 3시간 이내 마지막 정상 자료를 표시합니다. 아래 성공 조회 시각 기준입니다.</p>':''}${v.kind==='stale'?'<p>이전 성공 자료입니다. 최근 갱신 여부와 공식 원문을 확인하세요.</p>':''}${(v.unknown?s?.records||[]:v.records).map(r=>`<div class="source-row"><h3>${esc(r.type)} ${esc(r.level)}</h3><p>${esc(r.region)}</p><p>발표 ${esc(r.announced)} KST<br>발효 ${esc(r.effective)} KST${r.releaseEstimate?'<br>해제예고 '+esc(r.releaseEstimate):''}</p></div>`).join('')}${v.marineRecords?.length?'<h3>전국 해상 특보 · 관심지역 건수와 별도</h3>'+v.marineRecords.map(r=>`<div class="source-row"><h3>${esc(r.type)} ${esc(r.level)}</h3><p>${esc(r.region)}</p><p>발효 ${esc(r.effective)}</p></div>`).join(''):''}${(v.pendingRecords||[]).length?'<h3>예비·발효 예정</h3>'+v.pendingRecords.map(r=>`<div class="source-row"><h3>${esc(r.type)} ${esc(r.level)}</h3><p>${esc(r.region)}</p><p>발효 예정 ${esc(r.effective)} KST</p></div>`).join(''):''}${id==='weather'&&regions.length?'<p class="caption">육상·도서 시·군 기준입니다. 해상 특보는 위 별도 목록과 공식 원문을 확인하세요.</p>':''}${s?.count>0&&!(s.records||[]).length?'<p>발표 건수는 확인했지만 개별 사건의 위치·종류는 아직 검증되지 않았습니다. 공식 원문에서 확인하세요.</p>':''}<p class="caption">${s?.checkedAt?'마지막 성공 조회 '+esc(stamp(s.checkedAt)):''}${s?.attemptedAt&&s.attemptedAt!==s.checkedAt?' · 최근 시도 '+esc(stamp(s.attemptedAt)):''}</p>${s?.sourceUrl?`<a href="${esc(s.sourceUrl)}" target="_blank" rel="noopener noreferrer">공식 원문 확인 ↗</a>`:''}`)}

