 navigator.geolocation.getCurrentPosition(p=>{airLocationPending=false;airPosition={latitude:p.coords.latitude,longitude:p.coords.longitude,accuracy:Number.isFinite(p.coords.accuracy)?p.coords.accuracy:null};airLocationMessage='현재 위치 기준 · 이 화면을 닫으면 위치는 보관하지 않습니다.';const found=nearestCity(p.coords.latitude,p.coords.longitude,CITY_CENTERS);if(found)setWeatherCity(found.name,'current');else airLocationMessage='가까운 날씨 지원지점 없음 · 날씨 지역을 직접 선택해 주세요.';renderLocalCards()},e=>{airLocationPending=false;airPosition=null;airLocationMessage=e.code===1?'위치 허용 안 됨 · 브라우저 사이트 설정에서 위치 권한을 허용해 주세요. 관심지역 자료 유지':e.code===3?'위치 확인 시간 초과 · 관심지역 자료 유지':'위치 확인 실패 · 관심지역 자료 유지';renderLocalCards()},{enableHighAccuracy:false,timeout:8000,maximumAge:300000});
