  for(const g of groups){body+=`<h4>${esc(g.region)} <small>${g.items?.length||0}곳</small></h4>`;if(groupLabels[g.status])body+=`<p class="quality-warning">${esc(groupLabels[g.status])} · 주변 수치로 대체하지 않음</p>`;if(g.items?.length)body+=(g.items.length>100?'<p>첫 100곳 표시</p>':'')+airTable(g.items,{group:g.region,stamp})}
