 if(key==='earthquake'&&d?.items?.length)body+=localRows(['구분','발생시각','규모','진앙 위치'],d.items.map(r=>[r.type==='domestic'?'국내':'국외',stamp(r.occurredAt),r.magnitude,r.location]));
 if(key==='weatherWarning'&&d?.items?.length)body+=localRows(['발표시각','발표 제목'],d.items.map(r=>[stamp(r.publishedAt),r.title]));
 if(key==='weatherWarning'&&d?.status==='ok'&&d.count===0)body+='<p>오늘 발표목록 정상 조회 결과 0건</p>';
