function bindLocalControls(){const near=$('#detailAirLocation');if(near)near.onclick=()=>{requestAirLocation();$('#sheet').close()};const clear=$('#clearAirLocation');if(clear)clear.onclick=()=>{airPosition=null;airLocationMessage='내 주변 대기질을 보려면 위치를 허용해 주세요';renderLocalCards();localDataDetail('airQuality')};const city=$('#observationCity');if(city)city.onchange=async()=>{await setWeatherCity(city.value);localDataDetail('weather')};const air=$('#allAirStations');if(air)air.onclick=async()=>{airNationwide=true;await refreshLocalData(['airQuality']);localDataDetail('airQuality')};const selectedAir=$('#selectedAirStations');if(selectedAir)selectedAir.onclick=async()=>{airNationwide=false;await refreshLocalData(['airQuality']);localDataDetail('airQuality')};const warning=$('#officialWarningDetail');if(warning)warning.onclick=()=>localDataDetail('weatherWarning');const mapDetail=$('#officialMapDetail');if(mapDetail)mapDetail.onclick=()=>localDataDetail('administrativeMap')}
function localDataDetail(key){showSheet(localTitles[key],localContent(key));bindLocalControls()}
const localFetcher=latestRequest(fetch),supplyFetcher=latestRequest(fetch);
const allLocalParts=['weather','weatherForecast','airQuality','weatherWarning','earthquake','administrativeMap'];
let pendingLocalParts=[],localPromise=null,localURL='',touchRefresh=()=>{};
function refreshLocalData(parts=allLocalParts){
 touchRefresh();
 const requested=[...new Set([...pendingLocalParts,...parts])].sort();
 const q=new URLSearchParams({city:weatherCity,regions:airNationwide?'':regions.join(','),parts:requested.join(',')});
 // Explicit parts keep deferred road/flood providers out of home requests.
 const url='/api/local-data?'+q;if(localPromise&&localURL===url)return localPromise;
 const seq=++localRequest;pendingLocalParts=requested;localURL=url;
 const city=q.get('city'),isWeather=key=>key==='weather'||key==='weatherForecast';
 const resolve=(key,value)=>{
  if(isWeather(key))return displayCache.resolve(key+':'+city,{city,...value});
  return displayCache.resolve(key+':'+city+':'+q.get('regions'),value);
 };
 localPromise=localFetcher.run(url).then(next=>{
  if(seq===localRequest)localData={...localData,...Object.fromEntries(Object.entries(next).map(([key,value])=>[key,resolve(key,value)]))};
 }).catch(error=>{
  if(intentionalCancellation(error)||seq!==localRequest)return;
  const failed=localData?requested:requested.filter(isWeather);
  localData??={};
  for(const key of failed)localData[key]=resolve(key,{status:'unavailable',reason:'request_failed'});
 }).finally(()=>{if(seq===localRequest){pendingLocalParts=[];localPromise=null;renderLocalCards()}});
 return localPromise;
}
function renderLocalCards(){const forecast=$('#forecastPanel');if(forecast)forecast.innerHTML=forecastHTML(localData?.weatherForecast,{stamp});for(const[id,key]of[['currentObservation','weather'],['currentAir','airQuality'],['earthquakeCoverage','earthquake']]){const el=$('#'+id);if(el)el.textContent=key==='weather'?currentWeatherText(localData?.weather,localData?.weatherForecast):key==='airQuality'&&['ok','partial'].includes(localData?.airQuality?.status)?'대기질 · 측정소 '+localData.airQuality.count+'곳'+(localData.airQuality.status==='partial'?' · 일부 연결':''):(key==='airQuality'?'대기질 ':'')+connectionLabel(localData?.[key])}const weatherEl=$('#currentObservation');if(weatherEl){weatherEl.innerHTML=weatherCity?currentWeatherHTML(localData?.weather,localData?.weatherForecast):'날씨 지역 선택 필요 · 현재 위치 사용 또는 예보 지역 선택';$('#currentWeatherDetail').setAttribute('aria-label',currentWeatherText(localData?.weather,localData?.weatherForecast)+' · 3일 예보 보기')}const quake=$('#earthquakeCoverage');quake.textContent=earthquakeSummary(localData?.earthquake);quake.dataset.resultState=/^(국내|해외) /.test(quake.textContent)?'active':quake.textContent==='없음'?'confirmed':'unknown';const obs=$('#observationMeta');if(obs)obs.textContent=localData?.weather?.referenceAt?'관측 '+stamp(localData.weather.referenceAt):'관측시각 미확인';renderAirLocation();for(const id of ['currentObservation']){const el=$('#'+id);if(el)el.dataset.resultState=id==='currentObservation'&&Number.isFinite(localData?.weather?.temperature)&&!localData.weather.stale&&!localData.weather.reason?'confirmed':publicResultState(el.textContent)}updatePreviewContext({earthquake:localData?.earthquake,weatherCity})}
