function drawFlow(){if(!$('#powerFlowChart'))return;mountPowerFlow($('#powerFlowChart'),flowData||{},{date:today(),compare:$('#flowCompare').checked,compact:true},{legendElement:$('#flowLegend'),statusElement:$('#flowState'),tooltipElement:$('#flowTooltip')})}
const flowFetcher=latestRequest(fetch);
let supplyRequest=0,flowRequest=0,flowDateLoaded=null,supplyRetryTimer, supplyRetryAttempt=0;
function paintSupply(v){
 $('#supplyStatus').textContent=connectionLabel(v);$('#supplyCaption').textContent='전력거래소 · '+(v?.referenceAt?'자료 기준 '+stamp(v.referenceAt):'자료 기준시각 미확인')+(usesLastGood(v)?' · 이전 정상 자료':'');
 for(const[id,key,unit]of[['supplyRatio','reservePercent','%'],['supplyReserve','reserveMw','MW'],['supplyDemand','demandMw','MW']]){const el=$('#'+id),valid=['ok','stale'].includes(v?.status)&&Number.isFinite(v?.[key])&&v[key]>=0&&Number.isFinite(Date.parse(v.referenceAt));el.innerHTML=(valid?(unit==='MW'?(v[key]/1000).toFixed(1):v[key].toLocaleString('ko-KR',{maximumFractionDigits:1})):'?')+'<small>'+(unit==='MW'?'GW':unit)+'</small>';el.setAttribute('aria-label',el.textContent+(valid?'':' 미확인'));}
 updatePreviewContext({});
}
function retrySupply(){clearTimeout(supplyRetryTimer);if(supplyRetryAttempt>=3)return;const delay=[3000,45000,900000][supplyRetryAttempt++];supplyRetryTimer=setTimeout(()=>{if(!document.hidden)void refreshSupply({numbersOnly:true});},delay);}
async function refreshSupply({numbersOnly=false}={}){
 const seq=++supplyRequest,date=today();clearTimeout(supplyRetryTimer);
 const number=supplyFetcher.run('/api/power-flow?part=supply&date='+encodeURIComponent(date)).then(next=>{if(seq!==supplyRequest)return;const v=displayCache.resolve('supply',next.supply||{status:'unavailable',reason:'request_failed'});paintSupply(v);if(next.supply?.status==='ok'&&!next.supply.reason){supplyRetryAttempt=0}else retrySupply();}).catch(error=>{if(seq!==supplyRequest||intentionalCancellation(error))return;paintSupply(displayCache.resolve('supply',{status:'unavailable',reason:'request_failed'}));retrySupply();});
 const graphSeq=numbersOnly?flowRequest:++flowRequest;
 const graph=numbersOnly?Promise.resolve():flowFetcher.run('/api/power-flow?part=generation&date='+encodeURIComponent(date)).then(next=>{if(graphSeq!==flowRequest)return;flowData=displayCache.resolve('flow:'+date,next);flowDateLoaded=date;drawFlow();}).catch(error=>{if(graphSeq!==flowRequest||intentionalCancellation(error))return;flowData=displayCache.resolve('flow:'+date,{status:'unavailable',reason:'request_failed'});drawFlow();});
 await Promise.allSettled([number,graph]);
}
$('#flowDate').value=today();$('#flowDate').max=today();$('#flowDate').onchange=refreshSupply;$('#flowCompare').onchange=drawFlow;
$('#currentWeatherDetail').onclick=()=>weatherForecastSheet(true);
$('#currentAirDetail').onclick=()=>localDataDetail('airQuality');
$('#earthquakeCoverage').onclick=()=>localDataDetail('earthquake');$('#outageCoverage').onclick=outageNewsSheet;

let focusedLoading=null,demandLoading=null,focusedRetryTimer;
const focusedRuns={};
function paintFocused(){updatePreviewContext({kepcoHeadlines:(focusedCache.kepco?.items||[]).map(x=>x.title),powerHeadlines:focusedCache.power?.items||[],regions});renderOutageNews();}
async function refreshFocusedHeadlines(){
 if(naverPreview||document.hidden||focusedLoading)return focusedLoading;
 const hour=Math.floor(Date.now()/3600000);clearTimeout(focusedRetryTimer);
 for(const [category,d] of Object.entries(focusedCache))if(d?.status==='ok'&&Date.now()>=(Date.parse(d.validUntil)||Date.parse(d.checkedAt)+24*3600000))focusedCache[category]={status:'unavailable',items:[],reason:'last_good_expired'};paintFocused();
 focusedLoading=Promise.all(['kepco','outage','power'].map(async category=>{
  const state=focusedRuns[category]||(focusedRuns[category]={hour,attempts:0,due:0,done:false});
  if(state.due>Date.now())return;if(state.hour!==hour){state.hour=hour;state.attempts=0;}if(state.attempts>=4)return;state.attempts++;
  let next;try{const r=await fetch('/api/focused-news?category='+category,{cache:'no-store',signal:AbortSignal.timeout(30000)});next=r.ok?await r.json():{status:'unavailable',reason:'request_failed'};}catch{next={status:'unavailable',reason:'request_failed'};}
  focusedCache[category]=googleNewsDisplayCache.resolve('focused:'+category,next);
  state.done=next.status==='ok'&&!next.refreshError&&!next.stale;
  const serverDue=Date.parse(next.retryAt||next.expiresAt);state.due=Number.isFinite(serverDue)&&serverDue>Date.now()?serverDue:Date.now()+(next.status==='updating'?12000:7200000);paintFocused();
 })).finally(()=>{focusedLoading=null;const due=Object.values(focusedRuns).filter(s=>s.attempts<4).map(s=>s.due);for(const d of Object.values(focusedCache)){const expires=Date.parse(d?.validUntil)||Date.parse(d?.checkedAt)+24*3600000;if(d?.status==='ok'&&expires>Date.now())due.push(expires);}if(due.length)focusedRetryTimer=setTimeout(()=>{if(!document.hidden)void refreshFocusedHeadlines();},Math.max(1000,Math.min(...due)-Date.now()));});return focusedLoading;
}
async function focusedNewsSheet(category){
 showSheet(category==='outage'?'국내 정전 보도':'한전 주요 소식','<div id="focusedNewsSheet">보도 확인 중</div>');
 await refreshFocusedHeadlines();if(!$('#focusedNewsSheet')||!$('#sheet').open)return;
 const d=focusedCache[category],items=d?.items||[];
 $('#focusedNewsSheet').innerHTML='<p class="caption">Google 뉴스 RSS · 최근 72시간</p>'+(items.length?items.map(i=>'<article class="news-card"><h3><a href="'+esc(safeURL(i.url))+'" target="_blank" rel="noopener noreferrer">'+esc(i.title)+'</a></h3><p class="caption">'+esc(i.publisherName)+' · '+esc(stamp(i.publishedAt))+'</p></article>').join(''):'<p>'+(d?.status==='ok'?'조건에 맞는 확인된 보도가 없습니다.':'최신 보도를 확인하지 못했습니다.')+'</p>')+'<p class="caption">'+esc(d?.notice||'자료 확인 중')+'</p>';
}
async function refreshDemand(){
 if(naverPreview||demandLoading)return demandLoading;
 demandLoading=fetch('/api/power-demand',{cache:'no-store',signal:AbortSignal.timeout(30000)}).then(r=>r.ok?r.json():null).then(d=>{const key='demand:'+today(),out=displayCache.resolve(key,d||{status:'unavailable'});if(out){const forecast=displayCache.resolve('forecast:'+today(),d?.forecast||{status:'unavailable',reason:'request_failed'});if(forecast?.status==='ok')out.forecast=forecast;}updatePreviewContext({powerDemand:out})}).catch(()=>updatePreviewContext({powerDemand:displayCache.resolve('demand:'+today(),{status:'unavailable',today:[],previous:[],reason:'request_failed'})})).finally(()=>demandLoading=null);return demandLoading;
}
document.addEventListener('click',event=>{if(!naverPreview&&event.target.closest('#briefKepco')){event.preventDefault();event.stopImmediatePropagation();focusedNewsSheet('kepco')}},true);
refreshFocusedHeadlines();refreshDemand();
const armFocusedRefresh=()=>{clearTimeout(armFocusedRefresh.timer);armFocusedRefresh.timer=setTimeout(()=>{if(!naverPreview&&!document.hidden){refreshFocusedHeadlines();if(!naverSearchActive())void refresh();}armFocusedRefresh();},3600000-Date.now()%3600000+3500)};armFocusedRefresh();
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshFocusedHeadlines()});

refreshLocalData();refreshSupply();$('#refresh').addEventListener('click',()=>{refreshLocalData();refreshSupply()});

if(!naverPreview){const locationShown=mountLocationChoice({onAllow:requestAirLocation});if(!regionConfirmed&&!locationShown)regionSheet();if(weatherLocationMode!=='manual')void restoreLocationChoice({onAllow:requestAirLocation});}

const stopVisibleRefresh=onVisibleRefresh(document,()=>{if(resumeLocalParts.length||resumeSupply){resumeInterrupted();return}refreshLocalData();refreshSupply();refreshDemand();refreshPublicSignals()});
touchRefresh=stopVisibleRefresh.touch;
let resumeLocalParts=[],resumeSupply=false;
window.addEventListener('pagehide',()=>{if(localFetcher.cancel()){resumeLocalParts=[...pendingLocalParts];localRequest++;pendingLocalParts=[];localPromise=null}const numberCancelled=supplyFetcher.cancel(),graphCancelled=flowFetcher.cancel();if(numberCancelled||graphCancelled){resumeSupply=true;supplyRequest++;flowRequest++}});
function resumeInterrupted(){if(document.visibilityState!=='visible')return;const parts=resumeLocalParts,supply=resumeSupply;resumeLocalParts=[];resumeSupply=false;if(parts.length)refreshLocalData(parts);if(supply)refreshSupply();if(parts.length||supply)touchRefresh()}
window.addEventListener('pageshow',resumeInterrupted);
document.addEventListener('visibilitychange',resumeInterrupted);
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&supplyRetryAttempt>0)void refreshSupply();});

function mountNewsCategories(){
  if(document.getElementById('publicNewsCategories'))return;
  const section=document.getElementById('news');section.querySelector('h2').textContent='전력 뉴스';
  const controls=document.createElement('div');controls.id='publicNewsCategories';controls.className='naver-search-controls';controls.innerHTML='<div role="group" aria-label="뉴스 분류"><button data-public-scope="power" aria-pressed="true">전력 전반</button><button data-public-scope="local" aria-pressed="false">우리지역</button><button data-public-scope="kepco" aria-pressed="false">한전</button></div>';
  section.querySelector('#newsList').before(controls);controls.onclick=event=>{const button=event.target.closest('[data-public-scope]');if(!button)return;newsCategory=button.dataset.publicScope;filter='all';limit=5;controls.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));renderNews();};
}

// Visible-page refresh follows existing shared cache cadence; never polls while hidden.
let localRefreshTimer;
function armLocalRefresh(){clearTimeout(localRefreshTimer);if(document.hidden)return;localRefreshTimer=setTimeout(()=>{if(!document.hidden){refreshLocalData(['weather','weatherForecast','airQuality']);refreshPublicSignals();refreshSupply({numbersOnly:true});refreshDemand();}armLocalRefresh();},600000);}
document.addEventListener('visibilitychange',armLocalRefresh);armLocalRefresh();

// Mount the current shell synchronously, before waiting for provider configuration.
if(!naverPreview)renderPublicLayout();
